//! Differential ratchet for `src/engine/battleScriptSnatchOpcode.ts`.
//! Expected complete projected outputs, controls, and the exact missing-role
//! error are generated by executing the canonical TypeScript opcode handler;
//! regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-trysetsnatch-vectors.mjs`.
//!
//! Behavioral source is `Cmd_trysetsnatch` in
//! `reference/pokeemerald/src/battle_script_commands.c:9553-9565`. Its five
//! byte opcode/pointer form is `asm/macros/battle_script.inc:1144-1147`, and
//! `BattleScript_EffectSnatch` calls it at `data/battle_scripts_1.s:2543-2545`.

use std::collections::BTreeSet;

use factory_core::battle_script_trysetsnatch::{
    apply_battle_script_trysetsnatch, BattleScriptTrysetsnatchBattler,
    BattleScriptTrysetsnatchBattlerState, BattleScriptTrysetsnatchBattlersCount,
    BattleScriptTrysetsnatchBit, BattleScriptTrysetsnatchControl, BattleScriptTrysetsnatchOutcome,
    BattleScriptTrysetsnatchRoles, BattleScriptTrysetsnatchRules, BattleScriptTrysetsnatchTopology,
    BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS, BATTLE_SCRIPT_TRYSETSNATCH_BATTLER_COUNT,
    BATTLE_SCRIPT_TRYSETSNATCH_BATTLE_TYPE_DOUBLE,
};
use factory_core::battle_script_trysetsnatch_vectors_gen::{
    BattleScriptTrysetsnatchVectorCase, BattleScriptTrysetsnatchVectorState,
    BATTLE_SCRIPT_TRYSETSNATCH_ATTACKER_DOMAIN, BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS_COUNT_DOMAIN,
    BATTLE_SCRIPT_TRYSETSNATCH_BATTLE_TYPE_FLAGS_U32_EDGE_DOMAIN,
    BATTLE_SCRIPT_TRYSETSNATCH_BRANCH_CENSUS, BATTLE_SCRIPT_TRYSETSNATCH_CASES,
    BATTLE_SCRIPT_TRYSETSNATCH_CATEGORY_CENSUS,
    BATTLE_SCRIPT_TRYSETSNATCH_CURRENT_TURN_ACTION_NUMBER_DOMAIN,
    BATTLE_SCRIPT_TRYSETSNATCH_DOMAIN_CENSUS, BATTLE_SCRIPT_TRYSETSNATCH_VECTOR_CORPUS_SHA256,
};

fn bit(value: u8) -> BattleScriptTrysetsnatchBit {
    match value {
        0 => BattleScriptTrysetsnatchBit::Clear,
        1 => BattleScriptTrysetsnatchBit::Set,
        _ => panic!("generated bit must be 0 or 1, got {value}"),
    }
}

fn rules(value: BattleScriptTrysetsnatchVectorState) -> BattleScriptTrysetsnatchRules {
    let battlers_count = BattleScriptTrysetsnatchBattlersCount::try_from(value.battlers_count)
        .expect("generated canonical battlersCount");
    BattleScriptTrysetsnatchRules {
        battlers: core::array::from_fn(|index| BattleScriptTrysetsnatchBattlerState {
            steal_move: bit(value.steal_moves[index]),
            pp_not_affected_by_pressure: bit(value.pp_not_affected_by_pressure[index]),
        }),
        topology: BattleScriptTrysetsnatchTopology::new(battlers_count, value.battle_type_flags)
            .expect("generated canonical double-flag topology"),
        current_turn_action_number: value.current_turn_action_number,
        selector_roles: BattleScriptTrysetsnatchRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
    }
}

fn vector_state(value: BattleScriptTrysetsnatchRules) -> BattleScriptTrysetsnatchVectorState {
    BattleScriptTrysetsnatchVectorState {
        steal_moves: value.battlers.map(|battler| battler.steal_move.as_u8()),
        pp_not_affected_by_pressure: value
            .battlers
            .map(|battler| battler.pp_not_affected_by_pressure.as_u8()),
        battlers_count: value.topology.battlers_count().as_u8(),
        battle_type_flags: value.topology.battle_type_flags(),
        current_turn_action_number: value.current_turn_action_number,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
    }
}

#[test]
fn complete_projected_outputs_controls_exact_error_and_input_preservation_match_canonical_typescript(
) {
    assert_eq!(BATTLE_SCRIPT_TRYSETSNATCH_CASES.len(), 1302);
    for (case_index, case) in BATTLE_SCRIPT_TRYSETSNATCH_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptTrysetsnatchVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_trysetsnatch(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact missing-attacker error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptTrysetsnatchVectorCase,
    application: u8,
    prior: BattleScriptTrysetsnatchRules,
    outcome: BattleScriptTrysetsnatchOutcome,
) {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let acting_last =
        prior.current_turn_action_number == prior.topology.battlers_count().final_action_number();
    let expected_control = if acting_last {
        BattleScriptTrysetsnatchControl::FailJump
    } else {
        BattleScriptTrysetsnatchControl::Advance
    };

    assert_eq!(
        outcome.control, expected_control,
        "case {case_index} {} application {application}: source action-index control branch",
        case.label,
    );
    assert_eq!(
        outcome.rules.topology, prior.topology,
        "case {case_index} {} application {application}: changed source topology",
        case.label,
    );
    assert_eq!(
        outcome.rules.current_turn_action_number, prior.current_turn_action_number,
        "case {case_index} {} application {application}: changed source action byte",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed any selector role",
        case.label,
    );

    for battler in BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS {
        if battler == attacker {
            assert_eq!(
                outcome.rules.battlers[battler.index()].pp_not_affected_by_pressure,
                BattleScriptTrysetsnatchBit::Set,
                "case {case_index} {} application {application}: attacker PP was not Pressure-exempt",
                case.label,
            );
            assert_eq!(
                outcome.rules.battlers[battler.index()].steal_move,
                if acting_last {
                    prior.battlers[battler.index()].steal_move
                } else {
                    BattleScriptTrysetsnatchBit::Set
                },
                "case {case_index} {} application {application}: attacker steal bit did not preserve/arm",
                case.label,
            );
        } else {
            assert_eq!(
                outcome.rules.battlers[battler.index()],
                prior.battlers[battler.index()],
                "case {case_index} {} application {application}: changed sibling battler {}",
                case.label,
                battler.as_u8(),
            );
        }
    }
}

#[test]
fn valid_singles_doubles_attacker_action_edges_and_complete_u8_action_domain_are_covered() {
    let valid = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "valid-singles-doubles-attacker-action-boundary-matrix")
        .collect::<Vec<_>>();
    assert_eq!(valid.len(), 20);
    let observed_valid = valid
        .iter()
        .map(|case| {
            (
                case.initial.battlers_count,
                case.initial.attacker.expect("valid attacker").as_u8(),
                case.initial.current_turn_action_number,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_valid = [2_u8, 4]
        .into_iter()
        .flat_map(|battlers_count| {
            (0..battlers_count).flat_map(move |attacker| {
                (0..battlers_count).map(move |current_turn_action_number| {
                    (battlers_count, attacker, current_turn_action_number)
                })
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_valid, expected_valid);
    assert_eq!(
        valid
            .iter()
            .map(|case| case.initial.attacker.expect("valid attacker").as_u8())
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_TRYSETSNATCH_ATTACKER_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
        "all four source battlers must be covered by valid doubles cells",
    );

    let full_domain = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "current-turn-action-u8-full-domain-by-topology")
        .collect::<Vec<_>>();
    assert_eq!(full_domain.len(), 512);
    for battlers_count in BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS_COUNT_DOMAIN {
        let action_values = full_domain
            .iter()
            .filter(|case| case.initial.battlers_count == battlers_count)
            .map(|case| case.initial.current_turn_action_number)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            action_values,
            BATTLE_SCRIPT_TRYSETSNATCH_CURRENT_TURN_ACTION_NUMBER_DOMAIN
                .into_iter()
                .collect::<BTreeSet<_>>(),
            "battlersCount {battlers_count}: complete u8 action domain",
        );
        for case in full_domain
            .iter()
            .filter(|case| case.initial.battlers_count == battlers_count)
        {
            let expected_control = if case.initial.current_turn_action_number == battlers_count - 1
            {
                BattleScriptTrysetsnatchControl::FailJump
            } else {
                BattleScriptTrysetsnatchControl::Advance
            };
            assert_eq!(
                case.controls,
                &[expected_control],
                "{}: source equality branch",
                case.label,
            );
        }
    }
}

#[test]
fn selector_aliases_siblings_prior_bits_and_u32_topology_flags_are_preserved() {
    let selector_cases = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "complete-attacker-target-effect-fainted-selector-matrix")
        .collect::<Vec<_>>();
    assert_eq!(selector_cases.len(), 500);
    let role_value = |value: Option<BattleScriptTrysetsnatchBattler>| {
        value.map_or(-1_i8, |battler| battler.as_u8() as i8)
    };
    let observed = selector_cases
        .iter()
        .map(|case| {
            (
                role_value(case.initial.attacker),
                role_value(case.initial.target),
                role_value(case.initial.effect_battler),
                role_value(case.initial.fainted),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = (0_i8..4)
        .flat_map(|attacker| {
            (-1_i8..4).flat_map(move |target| {
                (-1_i8..4).flat_map(move |effect_battler| {
                    (-1_i8..4).map(move |fainted| (attacker, target, effect_battler, fainted))
                })
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);
    for case in selector_cases {
        let output = case.expected.expect("selector expected output");
        assert_eq!(
            output.attacker, case.initial.attacker,
            "{}: attacker preserved",
            case.label
        );
        assert_eq!(
            output.target, case.initial.target,
            "{}: target preserved",
            case.label
        );
        assert_eq!(
            output.effect_battler, case.initial.effect_battler,
            "{}: effectBattler sibling preserved",
            case.label,
        );
        assert_eq!(
            output.fainted, case.initial.fainted,
            "{}: fainted sibling preserved",
            case.label
        );
    }

    let bit_cases = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "complete-per-battler-steal-and-pp-prior-bit-matrix")
        .collect::<Vec<_>>();
    assert_eq!(bit_cases.len(), 256);
    let packed_bits = |case: &&BattleScriptTrysetsnatchVectorCase| {
        let pack = |bits: [u8; 4]| {
            bits.into_iter()
                .enumerate()
                .fold(0_u8, |word, (index, value)| word | (value << index))
        };
        pack(case.initial.steal_moves) | (pack(case.initial.pp_not_affected_by_pressure) << 4)
    };
    assert_eq!(
        bit_cases.iter().map(packed_bits).collect::<BTreeSet<_>>(),
        (0_u8..=u8::MAX).collect::<BTreeSet<_>>(),
        "all four steal and all four PP source bit values must be independently covered",
    );

    let flag_cases = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "battle-type-flags-u32-edge-preservation")
        .collect::<Vec<_>>();
    assert_eq!(flag_cases.len(), 8);
    assert_eq!(
        flag_cases
            .iter()
            .map(|case| case.initial.battle_type_flags)
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_TRYSETSNATCH_BATTLE_TYPE_FLAGS_U32_EDGE_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
    for case in flag_cases {
        let output = case.expected.expect("u32 flag expected output");
        assert_eq!(
            output.battle_type_flags, case.initial.battle_type_flags,
            "{}: source u32 gBattleTypeFlags word changed",
            case.label,
        );
        assert_eq!(
            (case.initial.battle_type_flags & BATTLE_SCRIPT_TRYSETSNATCH_BATTLE_TYPE_DOUBLE) != 0,
            case.initial.battlers_count == 4,
            "{}: generated canonical topology flag pairing",
            case.label,
        );
    }
}

#[test]
fn missing_attacker_alias_and_repeated_application_semantics_are_pinned() {
    let missing = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .filter(|case| case.category == "ordered-missing-attacker-role-errors")
        .collect::<Vec<_>>();
    assert_eq!(missing.len(), 3);
    for case in missing {
        assert_eq!(
            case.initial.attacker, None,
            "{}: missing attacker input",
            case.label
        );
        assert!(
            case.controls.is_empty(),
            "{}: error must not control",
            case.label
        );
        assert_eq!(
            case.expected_error,
            Some("Battle Script hit-chain command requires a attacker role"),
            "{}: exact canonical error",
            case.label,
        );
    }

    let alias = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .find(|case| case.label == "explicit_all_selector_alias_preserves_roles_and_arms_nonlast")
        .expect("explicit alias vector");
    assert_eq!(alias.initial.attacker, alias.initial.target);
    assert_eq!(alias.initial.attacker, alias.initial.effect_battler);
    assert_eq!(alias.initial.attacker, alias.initial.fainted);
    assert_eq!(alias.controls, &[BattleScriptTrysetsnatchControl::Advance]);
    let alias_output = alias.expected.expect("alias expected output");
    assert_eq!(alias_output.attacker, alias.initial.attacker);
    assert_eq!(alias_output.target, alias.initial.target);
    assert_eq!(alias_output.effect_battler, alias.initial.effect_battler);
    assert_eq!(alias_output.fainted, alias.initial.fainted);
    assert_eq!(alias_output.steal_moves[2], 1);
    assert_eq!(alias_output.pp_not_affected_by_pressure[2], 1);

    let repeated_nonlast = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .find(|case| {
            case.label
                == "repeated_nonlast_application_advances_twice_arms_steal_and_is_value_idempotent"
        })
        .expect("repeated nonlast vector");
    assert_eq!(repeated_nonlast.applications, 2);
    assert_eq!(
        repeated_nonlast.controls,
        &[
            BattleScriptTrysetsnatchControl::Advance,
            BattleScriptTrysetsnatchControl::Advance,
        ],
    );
    let nonlast_output = repeated_nonlast.expected.expect("repeated nonlast output");
    assert_eq!(nonlast_output.steal_moves[2], 1);
    assert_eq!(nonlast_output.pp_not_affected_by_pressure[2], 1);

    let repeated_last = BATTLE_SCRIPT_TRYSETSNATCH_CASES
        .iter()
        .find(|case| {
            case.label
                == "repeated_acting_last_application_fail_jumps_twice_sets_pp_and_preserves_steal"
        })
        .expect("repeated acting-last vector");
    assert_eq!(repeated_last.applications, 2);
    assert_eq!(
        repeated_last.controls,
        &[
            BattleScriptTrysetsnatchControl::FailJump,
            BattleScriptTrysetsnatchControl::FailJump,
        ],
    );
    let last_output = repeated_last.expected.expect("repeated acting-last output");
    assert_eq!(
        last_output.steal_moves[1],
        repeated_last.initial.steal_moves[1]
    );
    assert_eq!(last_output.pp_not_affected_by_pressure[1], 1);
}

#[test]
fn source_domains_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_TRYSETSNATCH_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_TRYSETSNATCH_ATTACKER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_TRYSETSNATCH_ATTACKER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_TRYSETSNATCH_BATTLERS_COUNT_DOMAIN, [2, 4]);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_CURRENT_TURN_ACTION_NUMBER_DOMAIN,
        core::array::from_fn(|value| value as u8),
    );
    assert_eq!(BATTLE_SCRIPT_TRYSETSNATCH_BATTLE_TYPE_DOUBLE, 1);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("selector-role-values-including-null", 5),
            ("canonical-battlers-count-values", 2),
            ("singles-valid-attacker-values", 2),
            ("doubles-valid-attacker-values", 4),
            ("current-turn-action-number-u8-values", 256),
            ("current-turn-action-u8-full-domain-probes", 512),
            ("valid-reachable-topology-attacker-action-cases", 20),
            ("complete-selector-matrix-cases", 500),
            ("per-battler-steal-and-pp-bit-combinations", 256),
            ("battle-type-flags-u32-edge-values", 8),
            ("typed-missing-attacker-role-cases", 3),
            ("application-count-values", 2),
            ("selector-roles-written-by-handler", 0),
            ("failure-pointer-fields-in-projection", 0),
            ("absolute-program-counter-fields-in-projection", 0),
            ("abi-exports-added", 0),
            ("unsupported-barriers-added", 0),
            ("generated-file-byte-limit-exclusive", 5_000_000),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_CATEGORY_CENSUS,
        [
            ("battle-type-flags-u32-edge-preservation", 8),
            (
                "complete-attacker-target-effect-fainted-selector-matrix",
                500,
            ),
            ("complete-per-battler-steal-and-pp-prior-bit-matrix", 256),
            ("current-turn-action-u8-full-domain-by-topology", 512),
            ("explicit-all-selector-alias-preservation", 1),
            ("ordered-missing-attacker-role-errors", 3),
            ("repeated-acting-last-application", 1),
            ("repeated-nonlast-application", 1),
            ("valid-singles-doubles-attacker-action-boundary-matrix", 20),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_BRANCH_CENSUS,
        [
            ("advance", 1032),
            ("advance-then-advance", 1),
            ("fail-jump", 265),
            ("fail-jump-then-fail-jump", 1),
            ("missing-attacker-role", 3),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETSNATCH_VECTOR_CORPUS_SHA256,
        "c97e457c24d5747fd5e6c51479d8467d6c73a6d4e2a97be0b10b7a0bca8d1dd3",
    );
}
